export function AccessibleError({
  fieldLabel = "{{fieldLabel}}",
  errorMessage = "{{errorMessage}}",
  associated = {{associated}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: 320, display: "flex", flexDirection: "column", gap: 6, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <label htmlFor="err-demo-field-r" style={{ fontWeight: 600, fontSize: 13 }}>{fieldLabel}</label>
      <input id="err-demo-field-r" type="text" defaultValue="not-an-email"
        aria-invalid={associated ? "true" : undefined}
        aria-describedby={associated ? "err-demo-msg-r" : undefined}
        style={{ padding: "10px 12px", borderRadius: 8, border: "2px solid " + accent, font: "inherit" }} />
      <p id="err-demo-msg-r" style={{ margin: 0, color: accent, fontSize: 13, fontWeight: 600 }}>{errorMessage}</p>
      {associated
        ? <p style={{ margin: "4px 0 0", fontSize: 12, color: "#1a7a44" }}>aria-invalid + aria-describedby wired up &mdash; the error is announced with the field</p>
        : <p style={{ margin: "4px 0 0", fontSize: 12, color: "#b3261e" }}>only a red border &mdash; a screen reader user never hears this message</p>}
    </div>
  );
}
